\section*{Adaptive Variance‑Scaled Gradient Descent (AVSGD)}

\section*{Mathematical Formulation}
Let $f:\mathbb{R}^{d}\rightarrow\mathbb{R}$ be the objective function.  
AVSGD maintains an exponential moving average of the (full) gradient,
\begin{equation}
    v_{t}= (1-\alpha)v_{t-1}+ \alpha \nabla f(x_{t}),\qquad v_{0}=0,
    \label{eq:vt}
\end{equation}
with a smoothing parameter $\alpha\in(0,1]$.  
Because $v_{t}$ is biased toward zero at early iterations, a bias‑corrected estimator is used:
\begin{equation}
    \hat v_{t}= \frac{v_{t}}{1-(1-\alpha)^{t}} .
    \label{eq:vtbias}
\end{equation}
The step size at iteration $t$ depends on the norm of $\hat v_{t}$:
\begin{equation}
    \eta_{t}= \frac{\eta}{\,1+\gamma \,\norm{\hat v_{t}}\,},
    \qquad \eta>0,\;\gamma>0 .
    \label{eq:et}
\end{equation}
The update of the decision variable is
\begin{equation}
    x_{t+1}= x_{t}-\eta_{t}\,\nabla f(x_{t}) .
    \label{eq:update}
\end{equation}
The hyper‑parameters of AVSGD are therefore
\[
\alpha\in(0,1],\qquad \eta>0,\qquad \gamma>0 .
\]

\section*{Pseudocode}
\begin{algorithm}[H]
\caption{Adaptive Variance‑Scaled Gradient Descent (AVSGD)}
\label{alg:avsgd}
\begin{algorithmic}[1]
\REQUIRE Initial point $x_{0}\in\mathbb{R}^{d}$, step‑size base $\eta$, smoothing $\alpha\in(0,1]$, scaling $\gamma>0$, max. iterations $T$.
\STATE $v_{0}\leftarrow 0$, $t\leftarrow 0$.
\WHILE{$t<T$}
    \STATE Compute the (full) gradient $g_{t}\leftarrow \nabla f(x_{t})$.
    \STATE Update the exponential moving average
    \[
        v_{t+1}\leftarrow (1-\alpha)v_{t}+ \alpha g_{t}.
    \]
    \STATE Bias‑corrected estimator
    \[
        \hat v_{t+1}\leftarrow \frac{v_{t+1}}{1-(1-\alpha)^{\,t+1}} .
    \]
    \STATE Adaptive step size
    \[
        \eta_{t+1}\leftarrow \frac{\eta}{1+\gamma \,\norm{\hat v_{t+1}} } .
    \]
    \STATE Gradient step
    \[
        x_{t+1}\leftarrow x_{t}-\eta_{t+1}\,g_{t}.
    \]
    \STATE $t\leftarrow t+1$.
\ENDWHILE
\RETURN $x_{T}$.
\end{algorithmic}
\end{algorithm}

\section*{Dry Run Example}
Consider the scalar quadratic $f(w)=(w-3)^{2}$, whose gradient is $\nabla f(w)=2(w-3)$.  
Initialize $w_{0}=0$, choose $\alpha=0.5$, $\eta=0.1$, $\gamma=1$, and run three iterations.

\begin{center}
\begin{tabular}{c|c|c|c|c}
\toprule
$t$ & $g_{t}= \nabla f(w_{t})$ & $v_{t+1}$ & $\eta_{t+1}$ & $w_{t+1}$\\
\midrule
0 & $-6$ & $v_{1}= (1-0.5)0+0.5(-6)=-3$ &
$\displaystyle \eta_{1}= \frac{0.1}{1+|{-6}|}= \frac{0.1}{7}=0.0142857$ &
$w_{1}=0-0.0142857(-6)=0.085714$\\[6pt]
1 & $-5.8286$ &
$v_{2}=0.5(-3)+0.5(-5.8286)=-4.4143$ &
$\displaystyle \eta_{2}= \frac{0.1}{1+5.8857}=0.01452$ &
$w_{2}=0.085714-0.01452(-5.8286)=0.17030$\\[6pt]
2 & $-5.6594$ &
$v_{3}=0.5(-4.4143)+0.5(-5.6594)=-5.0369$ &
$\displaystyle \eta_{3}= \frac{0.1}{1+5.7564}=0.01480$ &
$w_{3}=0.17030-0.01480(-5.6594)=0.25410$\\
\bottomrule
\end{tabular}
\end{center}
The corresponding objective values are
\[
f(w_{0})=9,\quad f(w_{1})\approx 8.495,\quad f(w_{2})\approx 8.005,\quad f(w_{3})\approx 7.538 .
\]
The example illustrates that, even with a simple adaptive rule, the iterates move toward the minimizer $w^{\star}=3$.

